 const aiVoiceUrls=new Map();
 async function speakAI(id,roomId){
  if(!P.supports(roomId)||typeof window.GIRLS_AI_API!=='string'||!window.GIRLS_AI_API)return;
  const msg=(S().chatMessages[roomId]||[]).find(m=>m.id===id&&m.autoReply&&m.from==='other'&&m.type==='text');
  if(!msg)return;if(playing===id){stopAudio();return;}
  stopAudio();const generation=playbackGeneration;let url=aiVoiceUrls.get(id);
  if(!url){
   toast('正在生成语音…');const abort=new AbortController(),tm=setTimeout(()=>abort.abort(),20000);
   try{
    const base=new URL(window.GIRLS_AI_API);if(base.protocol!=='https:')throw Error('https_required');
    const root=base.href.endsWith('/')?base.href.slice(0,-1):base.href;
    const response=await fetch(root+'/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',
      body:JSON.stringify({roomId,text:msg.text.slice(0,160)}),signal:abort.signal});
    if(!response.ok)throw Error('tts_failed');const payload=await response.json(),audioURL=new URL(payload.url);
    if(audioURL.protocol!=='https:')throw Error('audio_not_secure');
    url=audioURL.href;if(aiVoiceUrls.size>60)aiVoiceUrls.clear();aiVoiceUrls.set(id,url);
   }catch{if(generation===playbackGeneration)toast('语音暂时不可用，请检查后端配置');return;}
   finally{clearTimeout(tm);}
  }
  if(generation!==playbackGeneration||ctx.getRoute().app!=='room'||ctx.getRoute().id!==roomId)return;
  const next=new Audio(url);audio=next;playing=id;
  next.onended=()=>{if(audio===next)stopAudio();};
  next.onerror=()=>{if(audio===next){stopAudio();aiVoiceUrls.delete(id);toast('音频加载失败，请重试');}};
  try{await next.play();}
  catch{if(audio===next){stopAudio();toast('语音准备好了，请再点一次朗读');}}
 }
 async function toggleVoice(id,roomId){
  if(playing===id){stopAudio();return;}stopAudio();const generation=playbackGeneration,owner=S(),m=messages(roomId).find(x=>x.id===id);if(!m)return;
  let url=m.src;if(!url){const blob=await mediaLoad(m.blobKey);if(generation!==playbackGeneration||owner!==S()||ctx.getRoute().app!=='room'||ctx.getRoute().id!==roomId)return;if(!blob){toast('原声文件不可用，请重新导入');return;}url=URL.createObjectURL(blob);activeUrl=url;}
  const next=new Audio(url);audio=next;playing=id;
  next.onended=()=>{if(audio===next)stopAudio();};next.onerror=()=>{if(audio===next){stopAudio();toast('这段音频暂时无法播放');}};
  try{await next.play();if(audio!==next||generation!==playbackGeneration)return;if(!S().playedVoiceIds.includes(id)){S().playedVoiceIds.push(id);save();}const b=document.querySelector(`[data-action="wx-voice"][data-id="${id}"]`);b?.classList.add('playing');b?.parentElement.querySelector('.wx-voice-unheard')?.remove();}catch{if(audio===next){stopAudio();toast('点一下语音条重新播放');}}
 }
