 function calc(k){if(calcValue==='错误'&&k!=='AC'){calcValue='0';calcStored=null;calcOp=null;calcFresh=true;}if(/^\d$/.test(k)){calcValue=calcFresh||calcValue==='0'?k:(calcValue.length<12?calcValue+k:calcValue);calcFresh=false;}else if(k==='.'){if(calcFresh){calcValue='0';calcFresh=false;}if(!calcValue.includes('.'))calcValue+='.';}else if(k==='AC'){calcValue='0';calcStored=null;calcOp=null;calcFresh=false;}else if(k==='±')calcValue=String(-Number(calcValue));else if(k==='%')calcValue=String(Number(calcValue)/100);else{if(k==='='&&['520','0520'].includes(calcValue)&&calcStored===null){egg('calculator-0520','0520，记住了。');go('album',{id:'xiaowang'});return;}const value=Number(calcValue);if(calcStored!==null&&calcOp&&!calcFresh){const n=calcOp==='+'?calcStored+value:calcOp==='−'?calcStored-value:calcOp==='×'?calcStored*value:value===0?NaN:calcStored/value;calcValue=Number.isFinite(n)?String(Number(n.toPrecision(10))):'错误';}calcStored=k==='='?null:Number(calcValue);calcOp=k==='='?null:k;calcFresh=true;}const display=document.querySelector('.calc-display');if(display)display.textContent=calcValue;}
